ROOT=${APP_ROOT:-$(cd "$(dirname "$0")/.." && pwd)}
export APP_ROOT=$ROOT
case "$1" in
  avatar) bash "$ROOT/lib/avatar.sh" "$2" ;;
  appointment) bash "$ROOT/lib/appointment.sh" "$2" ;;
  *) echo "usage: app avatar|appointment <arg>" >&2; exit 2 ;;
esac

build/image/bin/app.text:
#!/bin/bash
# Entry point: app <command> [args]
ROOT=${APP_ROOT:-$(cd "$(dirname "$0")/.." && pwd)}
export APP_ROOT=$ROOT
case "$1" in
  avatar) bash "$ROOT/lib/avatar.sh" "$2" ;;
  appointment) bash "$ROOT/lib/appointment.sh" "$2" ;;
  *) echo "usage: app avatar|appointment <arg>" >&2; exit 2 ;;
esac

build/image/lib/appointment.sh.text:
#!/bin/bash
# Confirms an appointment date.
echo "status=201 date=$(bash "$APP_ROOT/vendor/datefmt/fmt.sh" "$1")"

build/image/lib/avatar.sh.text:
#!/bin/bash
# Stores a profile photo resized to 256 px.
out=$(bash "$APP_ROOT/vendor/imgtool/resize.sh" "$1" 256) || { echo "status=500"; exit 1; }
echo "status=201 avatar=$out"

build/image/vendor/imgtool/resize.sh.text:
#!/bin/bash
# imgtool 3.2.0: resize <file> <px> -> prints the resized file name
echo "${1%.*}-$2.png"

