tests/appointment_test.sh.text:
#!/bin/bash
out=$(bash bin/app appointment 20261105)
[ "$out" = "status=201 date=2026-11-05" ] || { echo "appointment: $out"; exit 1; }

tests/avatar_test.sh.text:
#!/bin/bash
out=$(bash bin/app avatar me.png)
[ "$out" = "status=201 avatar=me-256.png" ] || { echo "avatar: $out"; exit 1; }

tests/image_test.sh.text:
#!/bin/bash
# The production image must contain what lib/ needs at runtime (CLN-402).
bash scripts/build-image.sh >/dev/null || exit 1
out=$(APP_ROOT=build/image bash build/image/bin/app avatar me.png)
[ "$out" = "status=201 avatar=me-256.png" ] || { echo "image avatar: $out"; exit 1; }

